package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.component.query.Query;import com.hypixel.hytale.component.system.EntityEventSystem;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.event.events.ecs.*;import com.hypixel.hytale.server.core.inventory.ItemStack;import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;import com.hypixel.hytale.server.core.universe.*;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import static dev.astralreach.hytale.RocketRegistry.Cell;
/** All mutable resource/inventory reads occur on the owning world. Other worlds see immutable radio snapshots. */
final class RescueService{
 record Signal(String key,String world,Cell at,UUID owner,String name,Set<UUID>guests,long expires,boolean enabled,double oxygen,String condition,int depth,long sampled){boolean allows(UUID id){return owner.equals(id)||guests.contains(id);}boolean active(long now){return enabled&&expires>now;}boolean fresh(long now){return now-sampled<6000;}}
 private record Publication(long at,List<Signal>signals){}
 private static final Map<String,Publication>radio=new ConcurrentHashMap<>();
 static RescueRegistry data(Store<EntityStore>s){return s.getResource(AstralReachPlugin.rescueType);}
 private static volatile long nextRead;private static boolean reading;
 static synchronized void refreshSaved(){long now=System.currentTimeMillis();if(reading||now<nextRead)return;reading=true;nextRead=now+10000;java.util.concurrent.CompletableFuture.runAsync(()->{try(var worlds=java.nio.file.Files.list(Universe.get().getWorldsPath())){for(var folder:worlds.filter(java.nio.file.Files::isDirectory).toList()){String world=folder.getFileName().toString();if(Universe.get().getWorld(world)!=null)continue;var file=folder.resolve("resources/AstralRescueV1.json");if(!java.nio.file.Files.isRegularFile(file)||java.nio.file.Files.size(file)>16*1024*1024)continue;var encoded=org.bson.BsonDocument.parse(java.nio.file.Files.readString(file));var registry=new RescueRegistry();registry.restore(encoded.getString("BeaconsV1").getValue());var out=new ArrayList<Signal>();long readAt=System.currentTimeMillis();for(var e:registry.beacons.entrySet()){var b=e.getValue();out.add(new Signal(world+":"+e.getKey().key(),world,e.getKey(),b.owner(),b.ownerName(),Set.copyOf(b.guests().keySet()),b.expires(),b.enabled(),-1,"World unloaded · oxygen unknown",-1,readAt));}if(Universe.get().getWorld(world)==null)radio.put(world,new Publication(readAt,List.copyOf(out)));}}catch(java.io.IOException|IllegalArgumentException ignored){/* Retain only bounded, recently validated records across concurrent normal saves. */}finally{synchronized(RescueService.class){reading=false;}}});}
 static List<Signal>signals(UUID viewer){long now=System.currentTimeMillis();return radio.values().stream().filter(p->now-p.at()<15000).flatMap(p->p.signals().stream()).filter(e->e.allows(viewer)&&(e.active(now)||e.owner().equals(viewer))).sorted(Comparator.comparing(Signal::name).thenComparing(Signal::key)).toList();}
 static Signal find(String key,UUID viewer){return signals(viewer).stream().filter(e->e.key().equals(key)).findFirst().orElse(null);}
 static String key(Store<EntityStore>s,Cell at){return s.getExternalData().getWorld().getName()+":"+at.key();}
 static RescueBeacon own(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Cell at){var b=data(s).beacons.get(at);if(b==null||!b.owner().equals(p.getUuid())||!NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals("AR_RescueBeacon")||!RocketService.near(s,r,at))throw new IllegalArgumentException("Stand beside your own rescue beacon.");return b;}
 static void action(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,Cell at,String action,String name){var b=own(s,r,p,at);long now=System.currentTimeMillis();switch(action){
  case "Load"->{if(!b.canLoad(p.getUuid(),now))throw new IllegalArgumentException("The installed cell still has charge.");var inv=s.getComponent(r,Player.getComponentType()).getInventory().getCombinedStorageHotbarBackpack();var paid=YardInventory.take(inv,Map.of("AR_BeaconCell",1));if(paid.stream().mapToInt(ItemStack::getQuantity).sum()!=1)throw new IllegalArgumentException("Carry a Beacon Cell; craft it at the Astral Assembly Bench.");b.load(p.getUuid(),now);}
  case "Toggle"->b.toggle(p.getUuid(),now);
  case "Invite"->{var target=Universe.get().getPlayers().stream().filter(q->q.getUsername().equalsIgnoreCase(name.strip())).findFirst().orElseThrow(()->new IllegalArgumentException("Enter an online player's exact name."));b.invite(p.getUuid(),target.getUuid(),target.getUsername());}
  case "Revoke"->{var target=b.guests().entrySet().stream().filter(e->e.getValue().equalsIgnoreCase(name.strip())).findFirst().orElseThrow(()->new IllegalArgumentException("Enter an invited player's name to revoke access."));b.revoke(p.getUuid(),target.getKey());}
  default->{return;}}
  LunarEnvironment.interior(s,r,p,"AR_rescue_radio");publish(s);
 }
 static void publish(Store<EntityStore>s){long now=System.currentTimeMillis();var w=s.getExternalData().getWorld();var out=new ArrayList<Signal>();var iterator=data(s).beacons.entrySet().iterator();while(iterator.hasNext()){var e=iterator.next();var at=e.getKey();var b=e.getValue();var block=NativeBlocks.get(w,at);if(block!=null&&!NativeBlocks.base(block).equals("AR_RescueBeacon")){iterator.remove();continue;}
  // An unloaded mast remains registered; its clock continues and no chunk is force-loaded.
  double oxygen=-1;String condition="Owner absent · oxygen unknown";var owner=w.getPlayerRefs().stream().filter(p->p.getUuid().equals(b.owner())).findFirst().orElse(null);if(owner!=null){var r=owner.getReference();if(r!=null&&r.isValid()&&r.getStore()==s){var t=s.getComponent(r,TransformComponent.getComponentType());var player=s.getComponent(r,Player.getComponentType());if(t!=null&&player!=null&&t.getPosition().distanceSquared(at.x()+.5,at.y()+1,at.z()+.5)<=256*256){var inv=player.getInventory().getCombinedStorageHotbarBackpack();short slot=OxygenCanisters.active(inv);oxygen=slot<0?0:OxygenCanisters.remaining(inv.getItemStack(slot));condition=OxygenService.vacuum(s)?"Vacuum":"Breathable air";if(ExpeditionSuit.tier(s,r)==0)condition+=" · suit unsealed";else condition+=" · suit sealed";}}}
  int depth=w.getName().equals("AstralLune")?Math.max(0,LunarSurface.height((int)w.getWorldConfig().getSeed(),at.x(),at.z())-at.y()):0;out.add(new Signal(key(s,at),w.getName(),at,b.owner(),b.ownerName(),Set.copyOf(b.guests().keySet()),b.expires(),b.enabled(),oxygen,condition,depth,now));
  if(block!=null)NativeBlocks.stateOf(w,at,"AR_RescueBeacon",b.active(now)?"Active":"default");
 }radio.put(w.getName(),new Publication(now,List.copyOf(out)));}
 static void tick(Store<EntityStore>s,float dt){var d=data(s);d.elapsed+=Math.max(0,Math.min(1,dt));if(d.elapsed<1)return;d.elapsed=0;publish(s);refreshSaved();FieldService.tick(s);for(var p:s.getExternalData().getWorld().getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var player=s.getComponent(r,Player.getComponentType());if(player!=null&&player.getPageManager().getCustomPage() instanceof FieldPage page)page.refresh(s,r);}}
 static void shutdown(){radio.clear();FieldService.clear();}
 static final class Placement extends EntityEventSystem<EntityStore,PlaceBlockEvent>{Placement(){super(PlaceBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,PlaceBlockEvent e){if(e.isCancelled()||e.getItemInHand()==null||!e.getItemInHand().getItemId().equals("AR_RescueBeacon"))return;var p=c.getComponent(i,PlayerRef.getComponentType());var at=new Cell(e.getTargetBlock().x,e.getTargetBlock().y,e.getTargetBlock().z);s.getExternalData().getWorld().execute(()->{if(!e.isCancelled()&&NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals("AR_RescueBeacon")){data(s).beacons.put(at,new RescueBeacon(p.getUuid(),p.getUsername()));publish(s);}});}}
 static final class Breaking extends EntityEventSystem<EntityStore,BreakBlockEvent>{Breaking(){super(BreakBlockEvent.class);}@Override public Query<EntityStore>getQuery(){return PlayerRef.getComponentType();}@Override public void handle(int i,ArchetypeChunk<EntityStore>c,Store<EntityStore>s,CommandBuffer<EntityStore>b,BreakBlockEvent e){if(e.isCancelled())return;var root=NativeBlocks.root(s.getExternalData().getWorld(),new Cell(e.getTargetBlock().x,e.getTargetBlock().y,e.getTargetBlock().z));if(root==null||!data(s).beacons.containsKey(root))return;s.getExternalData().getWorld().execute(()->{if(!NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),root)).equals("AR_RescueBeacon")){data(s).beacons.remove(root);publish(s);}});}}
 private RescueService(){}
}
